function physics(){let mx=sim.moveX+(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),my=sim.moveY+(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0);if(Math.hypot(mx,my)<.12){mx=0;my=0}const l=Math.max(1,Math.hypot(mx,my));mx/=l;my/=l;const speed=sim.run||keys.has('ShiftLeft')?7:4;const motion=headingMotion(sim.yaw,mx,my,speed),vx=motion.x,vz=motion.z;if(sim.fp){sim.facing=sim.yaw}else if(Math.hypot(vx,vz)>.01){sim.facing=movementFacing(vx,vz)}if(sim.jump&&sim.grounded)sim.vy=8;sim.jump=false;sim.vy-=20*fixed;controller.computeColliderMovement(collider,{x:vx*fixed,y:sim.vy*fixed,z:vz*fixed});const m=controller.computedMovement(),p=body.translation();body.setNextKinematicTranslation({x:p.x+m.x,y:p.y+m.y,z:p.z+m.z});sim.grounded=controller.computedGrounded();if(sim.grounded&&sim.vy<0)sim.vy=0;world.step();if(p.y<-4){body.setTranslation({x:0,y:1.1,z:2},true);body.setNextKinematicTranslation({x:0,y:1.1,z:2});sim.vy=0;msg('שליו: לא נורא! נצייר גשר לפני שנחצה את המים.')}if(sim.bridge&&p.z<-17&&Math.abs(p.x)<5&&!sim.won){sim.won=true;msg('שליו: הגענו לטירה! זירת הבדיקה הושלמה.');$('#objective').textContent='כל הכבוד! תנועה, צבע וגשר — הושלמו'}}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.05);if(!sim.paused){sim.time+=dt;sim.cooldown=Math.max(0,sim.cooldown-dt);for(const t of targets){if(t.dead)continue;const x=t.homeX+Math.sin(sim.time*.7+t.phase)*.8,z=t.homeZ+Math.cos(sim.time*.7+t.phase)*.25;t.mesh.position.set(x,0,z);t.mesh.rotation.y=Math.atan2(body.translation().x-x,body.translation().z-z);t.body.setNextKinematicTranslation({x,y:1,z});}accumulator+=dt;while(accumulator>=fixed){physics();accumulator-=fixed}for(let i=sim.shots.length-1;i>=0;i--){const s=sim.shots[i];s.life-=dt;const old=s.mesh.position.clone();s.mesh.position.addScaledVector(s.dir,18*dt);const segment=new THREE.Line3(old,s.mesh.position);for(const t of targets){if(!t.dead&&segment.closestPointToPoint(t.mesh.position.clone().add(new THREE.Vector3(0,1.15,0)),true,new THREE.Vector3()).distanceTo(t.mesh.position.clone().add(new THREE.Vector3(0,1.15,0)))<1.2){hit(t);s.life=0;break}}if(s.life<=0){scene.remove(s.mesh);s.mesh.geometry.dispose();s.mesh.material.dispose();sim.shots.splice(i,1)}}for(let i=sim.effects.length-1;i>=0;i--){const e=sim.effects[i];e.life-=dt;e.mesh.position.addScaledVector(e.vel,dt);e.mesh.scale.setScalar(Math.max(.01,e.life/.7));if(e.life<=0){scene.remove(e.mesh);e.mesh.geometry.dispose();e.mesh.material.dispose();sim.effects.splice(i,1)}}}
const p=body.translation();player.position.set(p.x,p.y-.95,p.z);player.rotation.y=sim.facing;const eye=new THREE.Vector3(p.x,p.y+.7,p.z),forward=new THREE.Vector3(-Math.sin(sim.yaw)*Math.cos(sim.pitch),-Math.sin(sim.pitch),-Math.cos(sim.yaw)*Math.cos(sim.pitch));if(sim.fp){camera.position.copy(eye);camera.lookAt(eye.clone().add(forward))}else{const desired=eye.clone().addScaledVector(forward,-5.5);desired.y+=1.2;desired.y=Math.max(desired.y,.5);camera.position.copy(desired);camera.lookAt(eye.clone().addScaledVector(forward,2))}renderer.render(scene,camera);last+=dt;if(last>.35){miniRenderer.render(scene,miniCamera);last=0}}
